/**
 * tests for the justified layout — the Flickr/Google-Photos row
 * layout that Immich uses.
 *
 * The fixture is IMMICH'S OWN OUTPUT. It was generated by running
 * `@immich/justified-layout-wasm` — the Rust build Immich ships by
 * default — over 60 real photos from the library, at six row
 * configurations. Every case's boxes are the geometry Immich
 * computes for those photos.
 *
 * So this is not a test of "does the layout look right". It is a
 * test of "does Lustre compute the same geometry as Immich", box
 * for box, on the same photos.
 */
import { describe, expect, it } from 'vitest';
import fixture from './justified.fixture.json';
import { aspectFor, layoutJustified, DEFAULT_HEIGHT_TOLERANCE } from './justified';

interface Case {
  rowWidth: number;
  rowHeight: number;
  spacing: number;
  heightTolerance: number;
  containerWidth: number;
  containerHeight: number;
  boxes: number[][];
}

const photos = fixture.photos as [number, number][];
const cases = fixture.cases as Record<string, Case>;
const sources = photos.map(([w, h]) => ({ width: w, height: h }));

/**
 * Immich's WASM build accumulates in f32; JavaScript accumulates in
 * f64. Over 60 rows that shows up as a few thousandths of a pixel
 * of drift in the ACCUMULATED row offsets — not in the geometry.
 * The tolerance is well under a pixel.
 */
const EPSILON = 0.05;

describe('the justified layout matches Immich exactly', () => {
  for (const [label, c] of Object.entries(cases)) {
    it(`matches Immich's own output: ${label}`, () => {
      const got = layoutJustified(sources, {
        rowWidth: c.rowWidth,
        rowHeight: c.rowHeight,
        spacing: c.spacing,
        heightTolerance: c.heightTolerance
      });

      expect(got.placements.length).toBe(c.boxes.length);

      for (let i = 0; i < c.boxes.length; i++) {
        const [top, left, width, height] = c.boxes[i];
        const p = got.placements[i];
        expect(p.y, `box ${i} top`).toBeCloseTo(top, 1);
        expect(p.x, `box ${i} left`).toBeCloseTo(left, 1);
        expect(p.width, `box ${i} width`).toBeCloseTo(width, 1);
        expect(p.height, `box ${i} height`).toBeCloseTo(height, 1);
      }

      expect(got.height).toBeCloseTo(c.containerHeight, 1);
      expect(got.width).toBeCloseTo(c.containerWidth, 1);
    });
  }
});

describe('the layout invariants', () => {
  const opts = { rowWidth: 1440, rowHeight: 240, spacing: 0 };

  it('never crops a photo — every box has its own aspect ratio', () => {
    // The whole promise of the layout: the box IS the photo's shape.
    // Immich achieves it by scaling each photo to the row's height
    // and deriving its width from its own ratio.
    const got = layoutJustified(sources, opts);
    for (let i = 0; i < got.placements.length; i++) {
      const p = got.placements[i];
      const boxRatio = p.width / p.height;
      const photoRatio = photos[i][0] / photos[i][1];
      expect(Math.abs(boxRatio - photoRatio) / photoRatio).toBeLessThan(0.001);
    }
  });

  it('fills the row width — no gap at the right edge', () => {
    const got = layoutJustified(sources, opts);
    // Group the boxes into rows by their top edge.
    const rows = new Map<number, typeof got.placements>();
    for (const p of got.placements) {
      const key = Math.round(p.y);
      if (!rows.has(key)) rows.set(key, []);
      rows.get(key)!.push(p);
    }
    // Every row but the last is exactly the row width.
    const rowList = [...rows.values()];
    for (const row of rowList.slice(0, -1)) {
      const total = row.reduce((s, p) => s + p.width, 0) + opts.spacing * (row.length - 1);
      expect(total).toBeCloseTo(opts.rowWidth, 1);
    }
  });

  it('gives every photo in a row the same height', () => {
    // That is what "justified" means: the row has ONE height.
    const got = layoutJustified(sources, opts);
    const rows = new Map<number, number[]>();
    for (const p of got.placements) {
      const key = Math.round(p.y);
      if (!rows.has(key)) rows.set(key, []);
      rows.get(key)!.push(p.height);
    }
    for (const heights of rows.values()) {
      expect(Math.max(...heights) - Math.min(...heights)).toBeLessThan(EPSILON);
    }
  });

  it('uses the default tolerance when none is given', () => {
    expect(DEFAULT_HEIGHT_TOLERANCE).toBe(0.5);
    const withDefault = layoutJustified(sources, { rowWidth: 1440, rowHeight: 240 });
    const withExplicit = layoutJustified(sources, {
      rowWidth: 1440,
      rowHeight: 240,
      heightTolerance: 0.5
    });
    expect(withDefault.placements).toEqual(withExplicit.placements);
  });
});

describe('aspectFor', () => {
  it('is the photo own ratio', () => {
    expect(aspectFor({ width: 1000, height: 500 })).toBeCloseTo(2);
    expect(aspectFor({ width: 500, height: 1000 })).toBeCloseTo(0.5);
  });

  it('falls back to a square when the dimensions are unknown', () => {
    expect(aspectFor({})).toBe(1);
    expect(aspectFor({ width: null, height: null })).toBe(1);
    expect(aspectFor({ width: 0, height: 0 })).toBe(1);
    expect(aspectFor(null)).toBe(1);
    expect(aspectFor(undefined)).toBe(1);
  });
});

describe('edge cases', () => {
  it('lays out nothing for no photos', () => {
    const got = layoutJustified([], { rowWidth: 1440, rowHeight: 240 });
    expect(got.placements).toEqual([]);
    expect(got.height).toBe(0);
  });

  it('lays out one photo', () => {
    const got = layoutJustified([{ width: 1000, height: 500 }], {
      rowWidth: 1440,
      rowHeight: 240
    });
    expect(got.placements.length).toBe(1);
    // Immich's own build gives exactly this for a lone ratio-2 photo
    // in a 1440px row at rowHeight 240: the row takes the TARGET
    // height, and the photo's width follows from its own ratio.
    expect(got.placements[0].height).toBeCloseTo(240, 1);
    expect(got.placements[0].width).toBeCloseTo(480, 1);
  });

  it('does not divide by zero on a degenerate row width', () => {
    const got = layoutJustified([{ width: 100, height: 100 }], {
      rowWidth: 0,
      rowHeight: 0
    });
    expect(Number.isFinite(got.placements[0].width)).toBe(true);
    expect(Number.isFinite(got.placements[0].height)).toBe(true);
  });
});
